import pathlib,json,collections
R=pathlib.Path('/data/coding/scanweave/qualification/acr06');E=R/'hvc41c';L=R/'local';words=json.loads((E/'calibration-words.json').read_text());out=[]
cases=[('white',L/'hvc41b/controls/control/white/baseline.pdf.json',0),('financial-01',L/'ink33r/financial.pdf.json',0),('financial-02',L/'ink33r/financial.pdf.json',1),('reverse-panel',L/'hvc41b/controls/control/reverse_panel/baseline.pdf.json',0),('small-receipt',L/'hvc41b/controls/supplemental/small_receipt/baseline.pdf.json',0),('black-border',L/'hvc41b/controls/control/black_border/baseline.pdf.json',0),('photograph',L/'hvc41b/controls/control/photograph/baseline.pdf.json',0)]
for name,path,i in cases:
 r=json.loads(path.read_text())['conversion']['page_reports'][i];obs=r['reconstruction']['observations'];spans={x['symbol_id'].split('s')[0] for x in obs};actual=sum(x['units']>0 for x in r['regions']);w=[x for x in words if x['control']==name];mapped=[x for x in w if f"w{x['word_index']:06d}" in spans];accepted=[x for x in mapped if x['admitted']];rejected=[x for x in mapped if not x['admitted']];out.append({'control':name,'ocr_words':len(w),'admitted_words':sum(x['admitted'] for x in w),'baseline_text_regions':actual,'observed_distinct_span_ids':len(spans),'word_spans_with_observed_units':len(mapped),'admitted_word_spans_with_observed_units':len(accepted),'rejected_word_spans_with_observed_units':len(rejected),'span_counts_match':actual==len(spans),'rejection_reasons':dict(collections.Counter(k for x in rejected for k in x['reasons'])),'note':'Planner groups contiguous units by OCR span. Count equality and IDs support this mapping; the offline admission rule was not integrated into the planner.'})
(E/'region-summary.json').write_text(json.dumps(out,indent=2)+'\n');print([(r['control'],r['ocr_words'],r['admitted_words'],r['baseline_text_regions'],r['admitted_word_spans_with_observed_units'],r['span_counts_match']) for r in out])
